using System.Security.Claims;using HRM.Application.Contracts.Recruitment;using HRM.Components.Shared;using HRM.DTOs;using HRM.Models;using HRM.Models.Recruitment;using HRM.Services.Interfaces;using Microsoft.AspNetCore.Http;using Microsoft.EntityFrameworkCore;namespace HRM.Services;
public sealed class RecruitmentOfferService(IDbContextFactory<HrmTeContext> factory,IUserAccessService access,IOperationLogService logs,IHttpContextAccessor http):IRecruitmentOfferService{async Task<(int Org,int User)>Auth(){var o=await access.GetCurrentOrganisationIdAsync();var a=await access.RequireContextAsync();if(o<=0||!await access.HasOrganisationAccessAsync(o)||!await access.HasPermissionAsync("Recruitment.Manage"))throw new UnauthorizedAccessException("Recruitment management permission is required.");return(o,a.UserId);}public async Task<ServiceResult>CreateAsync(CreateRecruitmentOfferInput i,CancellationToken ct=default){if(i.MeritResultId<=0||string.IsNullOrWhiteSpace(i.TermsSnapshotJson)||i.TermsSnapshotJson.Length>16000)return ServiceResult.Fail("Provide the selected merit result and offer terms.");var(o,u)=await Auth();await using var d=await factory.CreateDbContextAsync(ct);var r=await(from m in d.RecruitmentMeritResults join p in d.RecruitmentResultPublications on m.RecruitmentResultPublicationId equals p.Id join v in d.RecruitmentVacancies on p.RecruitmentVacancyId equals v.Id where m.Id==i.MeritResultId&&v.OrganisationId==o select new{m,p,v}).SingleOrDefaultAsync(ct)??throw new UnauthorizedAccessException();if(!r.p.IsFinal)return ServiceResult.Fail("Results must be finalised after objections before an offer is issued.");if(r.m.Rank>r.v.VacancySlots)return ServiceResult.Fail("Only an applicant within the available vacancy slots may receive an offer.");if(await d.RecruitmentOffers.AnyAsync(x=>x.RecruitmentMeritResultId==r.m.Id,ct))return ServiceResult.Fail("An offer already exists for this merit result.");var l=await logs.CreateAsync(d,SharedConfig.OperationLogActionTypes.REQUESTS_CREATE,$"Recruitment offer issued for merit result {r.m.Id}.");d.RecruitmentOffers.Add(new RecruitmentOffer{RecruitmentMeritResultId=r.m.Id,OrganisationId=o,AppointmentAuthorityUserId=u,TermsSnapshotJson=i.TermsSnapshotJson,Status="Offered",OfferedAtUtc=DateTime.UtcNow,OperationLogId=l.OperationLogId});await d.SaveChangesAsync(ct);return ServiceResult.Ok("Offer issued with a frozen appointment-authority record.");}public async Task<ServiceResult>AcceptMyOfferAsync(int offerId,CancellationToken ct=default){var id=http.HttpContext?.User.FindFirstValue("idnumber")?.Trim();if(string.IsNullOrWhiteSpace(id))return ServiceResult.Fail("Sign in through eFaas before accepting an offer.");await using var d=await factory.CreateDbContextAsync(ct);var offer=await(from x in d.RecruitmentOffers join m in d.RecruitmentMeritResults on x.RecruitmentMeritResultId equals m.Id join app in d.RecruitmentApplications on m.RecruitmentApplicationId equals app.Id join applicant in d.RecruitmentApplicants on app.RecruitmentApplicantId equals applicant.Id where x.Id==offerId&&applicant.EfaasIdNumber==id select x).SingleOrDefaultAsync(ct)??throw new UnauthorizedAccessException("You may accept only your own offer.");if(offer.Status!="Offered")return ServiceResult.Fail("Only an issued offer may be accepted.");var l=await logs.CreateAsync(d,SharedConfig.OperationLogActionTypes.REQUESTS_UPDATE,$"Recruitment offer {offer.Id} accepted by eFaas-bound applicant.");offer.Status="Accepted";offer.AcceptedAtUtc=DateTime.UtcNow;offer.OperationLogId=l.OperationLogId;await d.SaveChangesAsync(ct);return ServiceResult.Ok("Offer accepted; onboarding integration may proceed.");}}
